-- Northvaine canonical schema (Postgres 16 + pgvector), v2 end state.
-- Generated by hand from migrations 0001+0002+0003+0004 and checked by T1.8 (T2.0 extends it).
-- Two layers
--   WORLD   = public facts about companies, shared and reusable (companies, documents, claims, events)
--   PRIVATE = everything belonging to one client workspace (profile, theses, cases, outcomes)
-- Rules: every fact traces to a document; generated JSON is validated by a versioned Pydantic schema;
-- nothing industry-specific lives in this file.
-- Conventions: learner columns use one CHECK list (world, org, buying, research, allocator).
-- strategy_version 0 means the defaults before the first learned version; it is not a foreign key
-- because shared rows have a NULL workspace while strategy_versions keys on a workspace.
-- Vector columns are vector(1024): Qwen/Qwen3-Embedding-8B via `dimensions=1024` (DECISIONS D7,
-- D14; northvaine/core/standards.EMBED_DIM_EXPECTED is the single source of the number). Each
-- carries a plain HNSW vector_cosine_ops index (the model L2-normalizes its output).

CREATE EXTENSION IF NOT EXISTS vector;
CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- ============ TENANCY ============
CREATE TABLE workspaces (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name          text NOT NULL,
  primary_domain text,                       -- the client own website
  created_at    timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE users (
  id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  email      text UNIQUE NOT NULL,
  name       text
);

CREATE TABLE memberships (
  workspace_id uuid REFERENCES workspaces(id) ON DELETE CASCADE,
  user_id      uuid REFERENCES users(id) ON DELETE CASCADE,
  role         text NOT NULL CHECK (role IN ('owner','manager','rep','ops')),
  territory    jsonb,                        -- e.g. {"countries":["DE","NL"],"products":["SP-630"]}
  PRIMARY KEY (workspace_id, user_id)
);

-- ============ WORLD LAYER (shared, public facts) ============
CREATE TABLE companies (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  primary_domain text UNIQUE,                -- canonical key for entity resolution
  name           text NOT NULL,
  aliases        text[] NOT NULL DEFAULT '{}',
  country        char(2),                    -- ISO 3166-1 alpha-2
  locality       text,
  industry_codes text[] NOT NULL DEFAULT '{}', -- e.g. ISIC or NAICS codes, prefixed by scheme
  attributes     jsonb NOT NULL DEFAULT '{}',  -- size band, type (distributor, contractor...)
  updated_at     timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE sources (
  id     uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name   text NOT NULL,                      -- 'tavily', 'ted', 'website', 'order_history'
  tier   text NOT NULL CHECK (tier IN ('official','company','reported','social','private','paid')),
  trust  real NOT NULL DEFAULT 0.5,          -- learned over time
  CONSTRAINT sources_name_key UNIQUE (name)  -- global provider rows; privacy lives on documents
);

CREATE TABLE documents (                     -- every fetched page or record, snapshotted
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  source_id     uuid REFERENCES sources(id),
  url           text NOT NULL,
  content_hash  text NOT NULL,               -- unchanged page = no new work
  title         text,
  text          text NOT NULL,               -- extracted plain text used for quote checks
  published_on  date,
  fetched_at    timestamptz NOT NULL DEFAULT now(),
  workspace_id  uuid REFERENCES workspaces(id), -- NULL = public; set = private (e.g. order CSV)
  available_at  timestamptz,                 -- when the page was knowable; NULL = not safe to replay
  external_id   text,                        -- the source's own id (TED publication-number...)
  group_key     text,                        -- links records of one thing (TED procedure-identifier)
  meta          jsonb NOT NULL DEFAULT '{}', -- structured fields of the record (schema_ver inside)
  UNIQUE (url, content_hash)
);
CREATE INDEX documents_group_key ON documents (source_id, group_key);
CREATE INDEX documents_external_id ON documents (source_id, external_id);
CREATE INDEX documents_available_at ON documents (available_at);

CREATE TABLE document_chunks (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  document_id uuid REFERENCES documents(id) ON DELETE CASCADE,
  text        text NOT NULL,
  embedding   vector(1024)
);
CREATE INDEX document_chunks_embedding_hnsw ON document_chunks
  USING hnsw (embedding vector_cosine_ops);

CREATE TABLE claims (                        -- the evidence ledger: one verified fact each
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  company_id    uuid REFERENCES companies(id),
  document_id   uuid NOT NULL REFERENCES documents(id),
  statement     text NOT NULL,               -- "Opened a second yard in Katy, Texas"
  source_quote  text NOT NULL,               -- exact sentence from documents.text
  quote_offset  int,                         -- where it was found (set by the code check)
  verified      boolean NOT NULL DEFAULT false,
  verified_by   text,                        -- 'code', 'code+llm'
  extracted_by  text NOT NULL,               -- model id that proposed it
  created_at    timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE event_concepts (                -- the learned event vocabulary, a tree
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  parent_id   uuid REFERENCES event_concepts(id) ON DELETE RESTRICT, -- NULL only at level 0
  level       int NOT NULL CHECK (level >= 0),
  label       text NOT NULL CHECK (label ~ '^[a-z][a-z0-9_]*$'),
  description text NOT NULL,
  embedding   vector(1024),
  status      text NOT NULL DEFAULT 'active' CHECK (status IN ('active','proposed','merged','retired')),
  merged_into uuid REFERENCES event_concepts(id), -- set when status = merged
  created_at  timestamptz NOT NULL DEFAULT now(),
  CHECK ((level = 0) = (parent_id IS NULL)),
  UNIQUE NULLS NOT DISTINCT (parent_id, label)
);
CREATE INDEX event_concepts_embedding_hnsw ON event_concepts
  USING hnsw (embedding vector_cosine_ops);

-- Level-0 seed, one concept per base event type.
INSERT INTO event_concepts (level, label, description) VALUES
  (0, 'facility_opened', 'A new site, plant, yard, branch or warehouse opened or announced'),
  (0, 'contract_awarded', 'A contract or tender award was made to the company'),
  (0, 'tender_published', 'The company published a tender or request for proposals'),
  (0, 'hiring_surge', 'A marked rise in open roles at the company'),
  (0, 'leadership_change', 'A senior leader joined, left or changed role'),
  (0, 'product_launch', 'The company launched or announced a product or service'),
  (0, 'market_entry', 'The company entered a new region or segment'),
  (0, 'trade_measure', 'A tariff, quota, duty or other trade rule changed'),
  (0, 'website_change', 'A material change to the company website'),
  (0, 'reorder_due', 'A past customer is due to reorder based on its history'),
  (0, 'quote_stale', 'A quote was sent and has had no reply for too long'),
  (0, 'inbound_question', 'A buyer or buyer agent asked a question through the Gateway');

CREATE TABLE events (                        -- something that CHANGED, in generic vocabulary
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  company_id   uuid REFERENCES companies(id),
  event_type   text NOT NULL,                -- the level-0 label, e.g. 'facility_opened','contract_awarded',
                                             -- 'hiring_surge','trade_measure','leadership_change',
                                             -- 'website_change','product_launch','reorder_due', ...
  occurred_on  date,
  details      jsonb NOT NULL DEFAULT '{}',  -- e.g. procurement codes and a value in euro
  cluster_id   uuid,                         -- same story from many sites = one cluster
  claim_ids    uuid[] NOT NULL,              -- an event without verified claims is not stored
  created_at   timestamptz NOT NULL DEFAULT now(),
  concept_id   uuid REFERENCES event_concepts(id), -- the finer concept, when one is known
  slots        jsonb NOT NULL DEFAULT '{}'   -- structured fields of the event
);
CREATE INDEX events_concept ON events (concept_id);

-- ============ PRIVATE LAYER (per client workspace) ============
CREATE TABLE business_profiles (             -- the "genome", versioned
  workspace_id uuid REFERENCES workspaces(id) ON DELETE CASCADE,
  version      int NOT NULL,
  schema_ver   text NOT NULL,                -- Pydantic model version that validated it
  profile      jsonb NOT NULL,               -- offer, regions, MOQ, anti-customers, capacity
  created_at   timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (workspace_id, version)
);

CREATE TABLE products (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id uuid REFERENCES workspaces(id) ON DELETE CASCADE,
  sku          text,
  name         text NOT NULL,
  hs_code      text,                         -- Harmonized System code where known
  attributes   jsonb NOT NULL DEFAULT '{}',  -- sizes, finishes, certifications
  public       boolean NOT NULL DEFAULT true -- shown on the Gateway profile
);

CREATE TABLE workspace_companies (           -- this client relationship to a world company
  workspace_id uuid REFERENCES workspaces(id) ON DELETE CASCADE,
  company_id   uuid REFERENCES companies(id),
  relation     text NOT NULL CHECK (relation IN ('customer','best_customer','prospect','competitor','suppressed')),
  owner_user   uuid REFERENCES users(id),    -- contact lock: one person per company
  PRIMARY KEY (workspace_id, company_id)
);

-- ============ LEARNING ============
CREATE TABLE hypotheses (                    -- one registry for every learner
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id uuid REFERENCES workspaces(id) ON DELETE CASCADE, -- NULL = shared
  learner     text NOT NULL CHECK (learner IN ('world','org','buying','research','allocator')),
  kind        text NOT NULL CHECK (kind ~ '^[a-z][a-z0-9_]*$'), -- pattern, concept_split, program, ...
  parent_id   uuid REFERENCES hypotheses(id), -- a refinement of a parent
  body        jsonb NOT NULL,
  schema_ver  text NOT NULL,
  status      text NOT NULL DEFAULT 'proposed'
              CHECK (status IN ('proposed','exploring','exploiting','degraded','retired','rejected')),
  origin      text NOT NULL CHECK (origin IN
              ('llm_prior','history_mining','world_lift','error_driven','missed_opportunity',
               'cross_org','owner')),
  proposed_at timestamptz NOT NULL DEFAULT now(),
  tests       jsonb NOT NULL DEFAULT '[]',
  decided_at  timestamptz,
  strategy_version int NOT NULL DEFAULT 0
);
CREATE INDEX hypotheses_lookup ON hypotheses (workspace_id, learner, kind, status);

CREATE VIEW patterns AS                      -- the pattern hypotheses, read as their own table
  SELECT id, workspace_id, learner, parent_id, body, schema_ver, status, origin,
         proposed_at, tests, decided_at, strategy_version
  FROM hypotheses WHERE kind = 'pattern';

CREATE TABLE theses (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id uuid REFERENCES workspaces(id) ON DELETE CASCADE,
  name         text NOT NULL,
  spec         jsonb NOT NULL,               -- trigger, follow_up_signals, disqualifiers,
                                             -- buyer_roles, window_days, event_types, queries
  origin       text NOT NULL CHECK (origin IN ('generated','user','discovered')),
  pinned       boolean NOT NULL DEFAULT false,
  status       text NOT NULL DEFAULT 'active' CHECK (status IN ('active','exploring','retired')),
  embedding    vector(1024),
  created_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX theses_embedding_hnsw ON theses USING hnsw (embedding vector_cosine_ops);

CREATE TABLE cases (                         -- one opportunity, inbound or outbound
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id uuid REFERENCES workspaces(id) ON DELETE CASCADE,
  company_id   uuid REFERENCES companies(id),
  direction    text NOT NULL CHECK (direction IN ('outbound','inbound')),
  thesis_id    uuid REFERENCES theses(id),
  pattern_id   uuid REFERENCES hypotheses(id),
  stage        text NOT NULL DEFAULT 'candidate' CONSTRAINT cases_stage_check CHECK (stage IN
               ('candidate','gated','investigated','briefed','approved','contacted','replied',
                'meeting','samples','quoted','won','lost','dismissed')),
               -- candidate → gated → investigated → briefed → approved → contacted
               -- → replied → meeting → samples → quoted → won | lost | dismissed
  verdict      jsonb,                        -- strength, confidence, why_now, angle, first_offer
  window_start date,
  window_end   date,
  assigned_to  uuid REFERENCES users(id),
  trace        jsonb NOT NULL DEFAULT '[]',  -- every stage it passed or failed, with reason
  created_at   timestamptz NOT NULL DEFAULT now(),
  updated_at   timestamptz NOT NULL DEFAULT now()
);
-- One open case per company, pattern and window; NULLs count as equal.
CREATE UNIQUE INDEX cases_open_unique ON cases (workspace_id, company_id, pattern_id, window_start)
  NULLS NOT DISTINCT WHERE stage NOT IN ('won','lost','dismissed');

CREATE TABLE case_evidence (
  case_id  uuid REFERENCES cases(id) ON DELETE CASCADE,
  claim_id uuid REFERENCES claims(id),
  stance   text NOT NULL CHECK (stance IN ('for','against','unknown')),
  PRIMARY KEY (case_id, claim_id)
);

CREATE TABLE contacts (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  company_id  uuid REFERENCES companies(id),
  role        text NOT NULL,                 -- 'procurement', 'owner', ...
  name        text,
  email       text,
  claim_id    uuid REFERENCES claims(id),    -- where we learned it
  verified    boolean NOT NULL DEFAULT false,
  workspace_id uuid REFERENCES workspaces(id) ON DELETE CASCADE -- NULL = world-layer contact
);

CREATE TABLE messages (                      -- drafts, outreach, replies, Gateway chat
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  case_id        uuid REFERENCES cases(id) ON DELETE CASCADE,
  direction      text NOT NULL CHECK (direction IN ('out','in')),
  channel        text NOT NULL,              -- 'email','chat','agent_mcp'
  counterpart    text NOT NULL CHECK (counterpart IN ('human','agent')),
  agent_domain   text,                       -- verified domain of a buyer agent
  subject        text,
  body           text NOT NULL,
  status         text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','approved','sent','received')),
  approved_by    uuid REFERENCES users(id),
  classification text,                       -- for replies: interested, question, not_now, no
  created_at     timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE quote_requests (                -- structured intake from the Gateway receptionist
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  case_id      uuid REFERENCES cases(id) ON DELETE CASCADE,
  items        jsonb NOT NULL,               -- [{product_id, quantity, unit}]
  destination  text,                         -- UN/LOCODE port where possible, e.g. 'USHOU'
  needed_by    date,
  notes        text,
  reply_due_at timestamptz,
  answered_at  timestamptz                   -- always answered by a person
);

CREATE TABLE feedback (
  id        uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  case_id   uuid REFERENCES cases(id) ON DELETE CASCADE,
  user_id   uuid REFERENCES users(id),
  rating    text NOT NULL CHECK (rating IN ('good','not_relevant','wrong_facts','later')),
  reason    text,                            -- 'too_small','wrong_region','already_customer',...
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE outcomes (                      -- the furthest stage reached, with value
  case_id    uuid PRIMARY KEY REFERENCES cases(id) ON DELETE CASCADE,
  stage      text NOT NULL CONSTRAINT outcomes_stage_check CHECK (stage IN
             ('candidate','gated','investigated','briefed','approved','contacted','replied',
              'meeting','samples','quoted','won','lost','dismissed')),
  value      numeric,
  currency   char(3),                        -- ISO 4217
  recorded_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE strategy_versions (             -- every nightly learning change, reversible
  workspace_id uuid REFERENCES workspaces(id) ON DELETE CASCADE,
  version      int NOT NULL,
  snapshot     jsonb NOT NULL,               -- all learner states, policy parameters and prompt versions
  changes      jsonb NOT NULL,               -- plain-language "what I learned"
  created_at   timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (workspace_id, version)
);

CREATE TABLE questions (                     -- the assistant keep-asking queue
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id uuid REFERENCES workspaces(id) ON DELETE CASCADE,
  question     text NOT NULL,
  reason       text NOT NULL,                -- which gap or pattern triggered it
  status       text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','asked','answered','skipped')),
  answer       text,
  asked_at     timestamptz
);

CREATE TABLE playbooks (                     -- the procedural half of a thesis
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id  uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  hypothesis_id uuid REFERENCES hypotheses(id),
  thesis_id     uuid REFERENCES theses(id),  -- migration path from theses
  name          text NOT NULL,
  spec          jsonb NOT NULL,              -- buyer roles, angle, first offer, follow-up signals
  schema_ver    text NOT NULL,
  status        text NOT NULL DEFAULT 'active' CHECK (status IN ('active','exploring','retired')),
  pinned        boolean NOT NULL DEFAULT false,
  created_at    timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE search_programs (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id  uuid REFERENCES workspaces(id) ON DELETE CASCADE, -- NULL = shared
  source_hypothesis uuid REFERENCES hypotheses(id),
  name          text NOT NULL,
  templates     jsonb NOT NULL DEFAULT '[]',
  sources       jsonb NOT NULL DEFAULT '[]',
  filters       jsonb NOT NULL DEFAULT '{}',
  schedule      jsonb NOT NULL DEFAULT '{}',
  status        text NOT NULL DEFAULT 'trial' CHECK (status IN ('active','trial','paused','retired')),
  yields        jsonb NOT NULL DEFAULT '{}',
  schema_ver    text NOT NULL,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE expectations (                  -- an event we expect to happen, so a miss can teach us
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id  uuid REFERENCES workspaces(id) ON DELETE CASCADE, -- NULL = shared
  company_id    uuid NOT NULL REFERENCES companies(id),
  concept_id    uuid NOT NULL REFERENCES event_concepts(id),
  hypothesis_id uuid REFERENCES hypotheses(id),
  window_start  date NOT NULL,
  window_end    date NOT NULL,
  origin        text NOT NULL CHECK (origin IN ('world','org','buying','research','allocator')),
  status        text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','met','missed')),
  value         numeric,                     -- expected value on the allocator scale
  met_event_id  uuid REFERENCES events(id),
  created_at    timestamptz NOT NULL DEFAULT now(),
  resolved_at   timestamptz,
  CHECK (window_end >= window_start)
);
CREATE INDEX expectations_open ON expectations (status, window_end);

CREATE TABLE beliefs (                       -- learned parameters, one row per learner key
  id               bigserial PRIMARY KEY,
  learner          text NOT NULL CHECK (learner IN ('world','org','buying','research','allocator')),
  workspace_id     uuid REFERENCES workspaces(id) ON DELETE CASCADE,
  strategy_version int NOT NULL DEFAULT 0,
  kind             text NOT NULL CHECK (kind ~ '^[a-z][a-z0-9_]*$'),
  key              text NOT NULL,
  params           jsonb NOT NULL,
  schema_ver       text NOT NULL,
  n_evidence       real NOT NULL DEFAULT 0 CHECK (n_evidence >= 0),
  prior_source     text,
  updated_at       timestamptz NOT NULL DEFAULT now(),
  UNIQUE NULLS NOT DISTINCT (learner, workspace_id, strategy_version, kind, key)
);

CREATE TABLE belief_source_calibration (     -- how far to trust each kind of prior
  id               bigserial PRIMARY KEY,
  workspace_id     uuid REFERENCES workspaces(id) ON DELETE CASCADE, -- NULL = pooled
  learner          text NOT NULL CHECK (learner IN ('world','org','buying','research','allocator')),
  prior_source     text NOT NULL,            -- e.g. llm_strong, owner_statement, history, cross_org
  bias             real NOT NULL DEFAULT 0,
  spread           real NOT NULL DEFAULT 1 CHECK (spread > 0),
  n_pairs          int NOT NULL DEFAULT 0 CHECK (n_pairs >= 0),
  strategy_version int NOT NULL DEFAULT 0,
  updated_at       timestamptz NOT NULL DEFAULT now(),
  UNIQUE NULLS NOT DISTINCT (workspace_id, learner, prior_source, strategy_version)
);

CREATE TABLE policy_params (                 -- tunable thresholds; history lives in strategy_versions.snapshot
  id               bigserial PRIMARY KEY,
  workspace_id     uuid REFERENCES workspaces(id) ON DELETE CASCADE, -- NULL = global default
  name             text NOT NULL CHECK (name ~ '^[a-z][a-z0-9_.]*$'),
  default_value    jsonb NOT NULL,
  current_value    jsonb NOT NULL,
  update_rule      text NOT NULL,            -- 'none' while stubbed
  metric           text NOT NULL,
  strategy_version int NOT NULL DEFAULT 0,
  updated_at       timestamptz NOT NULL DEFAULT now(),
  UNIQUE NULLS NOT DISTINCT (workspace_id, name)
);

CREATE TABLE decisions (                     -- the decision log with propensities, never cut
  id               bigserial PRIMARY KEY,
  workspace_id     uuid REFERENCES workspaces(id) ON DELETE CASCADE,
  kind             text NOT NULL CHECK (kind IN ('brief','search','investigation','question')),
  case_id          uuid REFERENCES cases(id) ON DELETE SET NULL,
  company_id       uuid REFERENCES companies(id),
  features         jsonb NOT NULL,
  choice           jsonb NOT NULL,
  value_estimate   real,
  propensity       real NOT NULL CHECK (propensity > 0 AND propensity <= 1),
  cost_usd         numeric(10,6) NOT NULL DEFAULT 0,
  strategy_version int NOT NULL DEFAULT 0,
  created_at       timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX decisions_log ON decisions (workspace_id, kind, created_at);

CREATE TABLE failure_attributions (          -- which part of the system a bad rating blames
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  feedback_id uuid NOT NULL REFERENCES feedback(id) ON DELETE CASCADE,
  code        text NOT NULL CHECK (code ~ '^[a-z][a-z0-9_]*$'), -- the failure codes
  learner     text NOT NULL CHECK (learner IN ('world','org','buying','research','allocator')),
  component   text NOT NULL,
  target_id   text,                          -- id of the belief, hypothesis, program or prompt, as text
  weight      real NOT NULL DEFAULT 1 CHECK (weight > 0 AND weight <= 1),
  confirmed   boolean NOT NULL DEFAULT false,
  created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE missed_opportunities (
  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id      uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  source            text NOT NULL CHECK (source IN ('inbound','win','public_award')),
  company_id        uuid REFERENCES companies(id),
  case_id           uuid REFERENCES cases(id) ON DELETE SET NULL,
  occurred_on       date NOT NULL,
  evidence_claim_id uuid REFERENCES claims(id),
  postmortem_status text NOT NULL DEFAULT 'pending' CHECK (postmortem_status IN
                    ('pending','not_surfaced','surfaced_dropped','surfaced_late','surfaced_in_time')),
  postmortem        jsonb NOT NULL DEFAULT '{}',
  created_at        timestamptz NOT NULL DEFAULT now(),
  analyzed_at       timestamptz
);

CREATE TABLE controls (                      -- matched controls for case-control tests, never cut
  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id        uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  hypothesis_id       uuid REFERENCES hypotheses(id) ON DELETE CASCADE,
  positive_company_id uuid NOT NULL REFERENCES companies(id),
  control_company_id  uuid NOT NULL REFERENCES companies(id),
  as_of               date NOT NULL,         -- point-in-time index date
  match_on            jsonb NOT NULL DEFAULT '{}',
  created_at          timestamptz NOT NULL DEFAULT now(),
  CHECK (positive_company_id <> control_company_id),
  UNIQUE NULLS NOT DISTINCT
    (workspace_id, hypothesis_id, positive_company_id, control_company_id, as_of)
);

CREATE TABLE lessons (                       -- no lesson without a recorded change
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id     uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  strategy_version int NOT NULL,
  learner          text NOT NULL CHECK (learner IN ('world','org','buying','research','allocator')),
  body             text NOT NULL,
  belief_change    jsonb NOT NULL,
  behaviour_change jsonb NOT NULL,
  created_at       timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (workspace_id, strategy_version)
    REFERENCES strategy_versions(workspace_id, version)
);

CREATE TABLE inbound_queries (               -- Gateway demand signal
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  channel      text NOT NULL,                -- open, like messages.channel
  counterpart  text NOT NULL CHECK (counterpart IN ('human','agent')),
  agent_domain text,
  query        text NOT NULL,                -- untrusted external text
  answered     boolean NOT NULL DEFAULT false,
  case_id      uuid REFERENCES cases(id) ON DELETE SET NULL,
  cluster_id   uuid,
  created_at   timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE case_open_questions (           -- companion of case_evidence
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  case_id        uuid NOT NULL REFERENCES cases(id) ON DELETE CASCADE,
  question       text NOT NULL,
  source_learner text NOT NULL CHECK (source_learner IN ('world','org','buying','research','allocator')),
  hypothesis_id  uuid REFERENCES hypotheses(id),
  status         text NOT NULL DEFAULT 'open' CHECK (status IN ('open','answered','dropped')),
  answer_claim_id uuid REFERENCES claims(id),
  created_at     timestamptz NOT NULL DEFAULT now(),
  resolved_at    timestamptz
);

-- ============ OPERATIONS ============
CREATE TABLE jobs (                          -- Postgres-backed queue
  id          bigserial PRIMARY KEY,
  kind        text NOT NULL,                 -- 'discover','filter','gate','investigate','verify','judge'
  payload     jsonb NOT NULL,
  status      text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','running','done','failed')),
  attempts    int NOT NULL DEFAULT 0,
  run_after   timestamptz NOT NULL DEFAULT now(),
  locked_at   timestamptz,
  error       text,
  created_at  timestamptz NOT NULL DEFAULT now(),
  finished_at timestamptz,
  max_attempts int NOT NULL DEFAULT 5 CHECK (max_attempts >= 1),
  locked_by   text,
  workspace_id uuid REFERENCES workspaces(id) ON DELETE CASCADE
);
CREATE INDEX jobs_claim ON jobs (run_after, id) WHERE status = 'queued';
CREATE INDEX jobs_lease ON jobs (locked_at) WHERE status = 'running';

CREATE TABLE llm_calls (                     -- cost and audit of every model call
  id           bigserial PRIMARY KEY,
  workspace_id uuid,
  case_id      uuid,
  model        text NOT NULL,
  purpose      text NOT NULL,
  input_tokens int, output_tokens int,
  cost_usd     numeric(10,6),
  ok           boolean,
  run_id       uuid,                        -- groups the calls of one RunContext (budget D1)
  prompt_version text,                      -- "<name>.v<N>" (DECISIONS D8); NULL for non-prompt calls
  latency_ms   int,
  error        text,                        -- set when ok = false
  provider     text NOT NULL DEFAULT 'nebius', -- which API served it (DECISIONS D15)
  created_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX llm_calls_created_at ON llm_calls (created_at);
CREATE INDEX llm_calls_workspace_created ON llm_calls (workspace_id, created_at);

CREATE TABLE audit_log (                     -- append-only: who did what, when
  id           bigserial PRIMARY KEY,
  workspace_id uuid,
  actor        text NOT NULL,                -- user id or 'system:<component>'
  action       text NOT NULL,
  target       text,
  details      jsonb,
  created_at   timestamptz NOT NULL DEFAULT now()
);
